INSERT INTO `creature_text` (`entry`,`groupid`,`id`,`text`,`type`,`language`,`probability`,`emote`,`duration`,`sound`,`comment`) VALUES
(7149,0,0,'%s becomes enraged!',16,0,100.0,0,0,0,'combat Enrage'),
(7157,0,0,'%s becomes enraged!',16,0,100.0,0,0,0,'combat Enrage'),
(7454,0,0,'%s grows increasingly crazed!',16,0,100.0,0,0,0,'combat Crazed'),
(8956,0,0,'%s becomes enraged!',16,0,100.0,0,0,0,'combat Enrage'),
(8958,0,0,'%s becomes enraged!',16,0,100.0,0,0,0,'combat Enrage'),
(9454,0,0,'%s becomes enraged!',16,0,100.0,0,0,0,'combat Enrage'),
(9462,0,0,'%s goes into a frenzy!',16,0,100.0,0,0,0,'combat Frenzy'),
(9516,0,0,'Pathetic mortal... I will build a new empire atop your corpse!',14,0,100.0,0,0,0,'Lord Banehollow'),
(9516,1,0,'No... NO! This is my domain! You cannot have... it...',14,0,100.0,0,0,0,'Lord Banehollow'),
(14344,0,0,'%s becomes enraged!',16,0,100.0,0,0,0,'combat Enrage'),
(47308,0,0,'BEES! Jump in water to get them off!',42,0,100.0,0,0,0,'Felwood Honey Bunny'),
(47339,0,0,'Go away, kid, you\'re botherin\' me!',12,0,100.0,0,0,0,'Impsy'),
(47339,1,0,'Right in the face! Ow ow ow...',14,0,100.0,0,0,0,'Impsy'),
(47339,2,0,'Catch Impsy in the sack!',41,0,100.0,0,0,0,'Impsy'),
(47366,0,0,'I\'ll talk, I\'ll talk! Anything! Just keep that perfumed bag away from me!',12,0,100.0,0,0,0,'Impsy'),
(47369,0,0,'%s flees in terror!',16,0,100.0,0,0,0,'Jadefire Imp to Rainbow! - Channeller'),
(47369,0,1,'%s screams at the top of its lungs!',16,0,100.0,0,0,0,'Jadefire Imp to Rainbow! - Channeller'),
(47369,0,2,'%s starts sobbing uncontrollably!',16,0,100.0,0,0,0,'Jadefire Imp to Rainbow! - Channeller'),
(47369,1,0,'The colors! Nooooooooooooooo!',14,0,100.0,0,0,0,'Jadefire Imp to Rainbow! - Channeller'),
(47369,1,1,'AAAAAAAAAAAAHHH!!',14,0,100.0,0,0,0,'Jadefire Imp to Rainbow! - Channeller'),
(47369,1,2,'It burns! IT BURNS!',14,0,100.0,0,0,0,'Jadefire Imp to Rainbow! - Channeller'),
(47369,1,3,'It\'s so intense!',14,0,100.0,0,0,0,'Jadefire Imp to Rainbow! - Channeller'),
(47369,1,4,'It\'s too much!',14,0,100.0,0,0,0,'Jadefire Imp to Rainbow! - Channeller'),
(47369,1,5,'Get it away!',14,0,100.0,0,0,0,'Jadefire Imp to Rainbow! - Channeller'),
(47369,1,6,'Make it stop! MAKE IT STOP!',14,0,100.0,0,0,0,'Jadefire Imp to Rainbow! - Channeller'),
(47556,0,0,'Hee hee... hee hee hee... ha ha ha!',12,0,100.0,0,0,0,'Drizle'),
(47556,1,0,'Don\'t call me dummy, dummy!',12,0,100.0,0,0,0,'Drizle'),
(47556,2,0,'Run!',12,0,100.0,0,0,0,'Drizle'),
(47558,0,0,'Shh! They can hear you, dummy!',12,0,100.0,0,0,0,'Ferli'),
(47558,1,0,'Ow! Now they can see us!',12,0,100.0,0,0,0,'Ferli'),
(47679,0,0,'Kitty... KITTY! I\'M SO SORRY, KITTY! COME BACK! DON\'T LEAVE ME LIKE THIS!',14,0,100.0,0,0,0,'on Aggro Text'),
(47692,0,0,'Urrrrrrgh...',12,0,100.0,0,0,0,'Altsoba Ragetotem'),
(47692,1,0,'HLORRHGH!',14,0,100.0,0,0,0,'Altsoba Ragetotem'),
(47696,0,0,'Open wide, Mr. Tauren! Here comes the hippogryph into the roost!',12,0,100.0,0,0,0,'Kelnir Leafsong'),
(47842,0,0,'Your death will tell a different story!',14,0,100.0,0,0,0,'Arch Druid Navarax to Player'),
(47923,0,0,'Blind fool! You have no idea what you are doing!',14,0,100.0,0,0,0,'Feronas Sindweller'),
(47923,1,0,'Enough! Stay your hand!',14,0,100.0,0,0,0,'Feronas Sindweller'),
(48154,0,0,'It sees us...',12,0,100.0,0,0,0,'Jadefire Shifter'),
(48154,0,1,'Tear its eyes out!',12,0,100.0,0,0,0,'Jadefire Shifter'),
(48154,0,2,'You will tell no one!',12,0,100.0,0,0,0,'Jadefire Shifter'),
(48154,0,3,'Intruder...',12,0,100.0,0,0,0,'Jadefire Shifter'),
(48331,0,0,'Deep breaths... deep breaths!',12,0,100.0,0,0,0,''),
(48331,0,1,'I\'m okay!',12,0,100.0,0,0,0,''),
(48331,0,2,'Pull it together!',12,0,100.0,0,0,0,''),
(48331,0,3,'That felt kinda good!',12,0,100.0,0,0,0,''),
(48331,0,4,'That\'s enough! Time to act like a goblin!',12,0,100.0,0,0,0,''),
(48331,0,5,'Wow! Where am I?!',12,0,100.0,0,0,0,''),
(48331,0,6,'You don\'t have to tell me that twice!',12,0,100.0,0,0,0,''),
(48332,0,0,'If you\'ve been wrasslin\' with oil, be sure to avoid all sources of sparks or open flame, such as candles, lighters, mages, Kester\'s shop, and Deputy Clunky!',14,0,100.0,0,0,0,'Deputy Clunky'),
(48332,0,1,'Always wear head protection while on the job! You never know when Miss Darla might have to smack you in the face!',14,0,100.0,0,0,0,'Deputy Clunky'),
(48332,0,2,'When you\'re doggone tired, it\'s mighty easy to slip up on the job, pardner! Be sure to get at least two hours\' rest between shifts!',14,0,100.0,0,0,0,'Deputy Clunky'),
(48344,0,0,'KROSHIUS CRUSH!',14,0,100.0,0,0,0,'Kroshius'),
(48487,0,0,'What is going on in here?!',12,0,100.0,5,0,0,'Whisperwind Druid to Player'),
(48487,1,0,'The Arch Druid... how in the world...?',12,0,100.0,274,0,0,'Whisperwind Druid to Player'),
(48487,2,0,'I... I must tell the others. You should find Huntress Selura right away.',12,0,100.0,1,0,0,'Whisperwind Druid to Player');
